import { useCallback, useState } from 'react';
import {
  ReactFlow,
  addEdge,
  useNodesState,
  useEdgesState,
  Background,
  Controls,
  MiniMap,
  useReactFlow
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import FiberDeviceNode from './FiberDeviceNode';

const nodeTypes = { fiberDevice: FiberDeviceNode };

export default function NetworkFlow({ onElementSelect }) {
  const [nodes, setNodes, onNodesChange] = useNodesState([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState([]);
  const { screenToFlowPosition } = useReactFlow();
  const [reactFlowInstance, setReactFlowInstance] = useState(null);

  const onConnect = useCallback(
    (params) => {
      const newEdge = {
        ...params,
        id: `edge-${params.source}-${params.target}-${Date.now()}`,
        label: 'Fiber Link',
        animated: true,
        style: { stroke: '#64748b', strokeWidth: 2 },
        labelStyle: { fill: '#334155', fontWeight: 500, fontSize: '11px' },
        labelShowBg: true,
        labelBgStyle: { fill: '#fff', stroke: '#cbd5e1', strokeWidth: 1 },
        labelBgPadding: [4, 4]
      };
      setEdges((eds) => addEdge(newEdge, eds));
    },
    [setEdges]
  );

  const onDragOver = useCallback((event) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = 'move';
  }, []);

  const onDrop = useCallback(
    (event) => {
      event.preventDefault();
      const type = event.dataTransfer.getData('application/reactflow');
      
      if (!type || !reactFlowInstance) return;

      const position = reactFlowInstance.screenToFlowPosition({
        x: event.clientX,
        y: event.clientY,
      });

      const newNode = {
        id: `${type}-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        type: 'fiberDevice',
        position,
        data: { 
          type, 
          hostname: '', 
          ip: '',
          label: type.toUpperCase()
        },
      };
      
      setNodes((nds) => [...nds, newNode]);
    },
    [reactFlowInstance, setNodes]
  );

  const onNodeClick = useCallback((_, node) => {
    onElementSelect({ type: 'node', id: node.id });
  }, [onElementSelect]);

  const onEdgeClick = useCallback((_, edge) => {
    onElementSelect({ type: 'edge', id: edge.id });
  }, [onElementSelect]);

  const onPaneClick = useCallback(() => {
    onElementSelect(null);
  }, [onElementSelect]);

  return (
    <ReactFlow
      nodes={nodes}
      edges={edges}
      onNodesChange={onNodesChange}
      onEdgesChange={onEdgesChange}
      onConnect={onConnect}
      onDragOver={onDragOver}
      onDrop={onDrop}
      onNodeClick={onNodeClick}
      onEdgeClick={onEdgeClick}
      onPaneClick={onPaneClick}
      onInit={setReactFlowInstance}
      nodeTypes={nodeTypes}
      fitView
      fitViewOptions={{ padding: 0.2 }}
      className="react-flow-container"
      minZoom={0.2}
      maxZoom={2}
    >
      <Background color="#e2e8f0" gap={24} size={1} />
      <Controls showInteractive={false} />
      <MiniMap 
        nodeColor={(node) => {
          const colors = { router: '#ef4444', switch: '#f59e0b', olt: '#10b981', ont: '#3b82f6' };
          return colors[node.data?.type] || '#64748b';
        }}
        maskColor="rgba(241, 245, 249, 0.85)"
      />
    </ReactFlow>
  );
}
